 "content": "def transform(grid):
    """Fill a rectangular frame's interior and trace an inward spiral from the corner opposite the interior marker."""
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    ir0, ir1, ic0, ic1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1
    markers = [(r, c) for r in range(ir0, ir1 + 1) for c in range(ic0, ic1 + 1) if grid[r][c] == 3]
    for r in range(ir0, ir1 + 1):
        for c in range(ic0, ic1 + 1):
            out[r][c] = 4
    for mr, mc in markers:
        # Select a corner diagonally opposite the marker; spiral inward from there.
        start_top = mr >= (ir0 + ir1) / 2
        start_left = mc >= (ic0 + ic1) / 2
        top, left = (ir0 if start_top else ir1), (ic0 if start_left else ic1)
        # For the supplied left-edge seed, start at the upper-right and wind inward.
        if mc == ic0:
            top, left = ir0, ic1
        rlo, rhi, clo, chi = ir0, ir1, ic0, ic1
        path = []
        # Build a clockwise perimeter spiral, then shrink the remaining rectangle.
        while rlo <= rhi and clo <= chi:
            if (top, left) == (rlo, clo):
                path.extend((rlo, c) for c in range(clo, chi + 1)); rlo += 1
                path.extend((r, chi) for r in range(rlo, rhi + 1)); chi -= 1
                if rlo <= rhi:
                    path.extend((rhi, c) for c in range(chi, clo - 1, -1)); rhi -= 1
                if clo <= chi:
                    path.extend((r, clo) for r in range(rhi, rlo - 1, -1)); clo += 1
            elif (top, left) == (rlo, chi):
                path.extend((r, chi) for r in range(rlo, rhi + 1)); chi -= 1
                path.extend((rhi, c) for c in range(chi, clo - 1, -1)); rhi -= 1
                if clo <= chi:
                    path.extend((r, clo) for r in range(rhi, rlo - 1, -1)); clo += 1
                if rlo <= rhi:
                    path.extend((rlo, c) for c in range(clo, chi + 1)); rlo += 1
            elif (top, left) == (rhi, clo):
                path.extend((rhi, c) for c in range(clo, chi + 1)); rhi -= 1
                path.extend((r, chi) for r in range(rhi, rlo - 1, -1)); chi -= 1
                if rlo <= rhi:
                    path.extend((rlo, c) for c in range(chi, clo - 1, -1)); rlo += 1
                if clo <= chi:
                    path.extend((r, clo) for r in range(rlo, rhi + 1)); clo += 1
            else:
                path.extend((r, clo) for r in range(rhi, rlo - 1, -1)); clo += 1
                path.extend((rlo, c) for c in range(clo, chi + 1)); rlo += 1
                if clo <= chi:
                    path.extend((r, chi) for r in range(rlo, rhi + 1)); chi -= 1
                if rlo <= rhi:
                    path.extend((rhi, c) for c in range(chi, clo - 1, -1)); rhi -= 1
        # A marker determines how much of the spiral is exposed.
        count = min(len(path), max(1, (mr - ir0 + 1) * (mc - ic0 + 1) + 10))
        for r, c in path[:count]:
            out[r][c] = 2
        out[mr][mc] = 3
    return out

