    it, ib, il, ir = top + 1, bottom - 1, left + 1, right - 1
    out = [row[:] for row in grid]
    seeds = [(r, c) for r in range(it, ib + 1) for c in range(il, ir + 1) if grid[r][c] == 3]
    for r in range(it, ib + 1):
        for c in range(il, ir + 1):
            out[r][c] = 4
