    motif = {(1, c) for c in range(6)} | {(2, 5)}
    motif |= {(3, c) for c in range(4)} | {(3, 5)}
    motif |= {(4, 3), (4, 5), (5, 3), (5, 5), (6, 3), (6, 5)}
